panel["quality_key"]=np.select([panel.MODIS_source_status.eq("interpolated"),panel.MODIS_coverage_proxy.lt(COVERAGE_CUTOFF)],["interpolated","low"],default="high")
for k in range(4):
    g=panel.groupby("upazila",sort=False)
    for pre,col in [("ndvi","ndvi_z"),("evi","evi_z")]: panel[f"{pre}_z_lag{k}"]=g[col].shift(-k)
    for pre,col in [("ndvi","NDVI_monthly"),("evi","EVI_monthly")]: panel[f"{pre}_value_lag{k}"]=g[col].shift(-k)
    panel[f"target_status_lag{k}"]=g["MODIS_source_status"].shift(-k); panel[f"target_cov_lag{k}"]=g["MODIS_coverage_proxy"].shift(-k); panel[f"target_quality_lag{k}"]=g["quality_key"].shift(-k)

def add_runs(df,thr):
    out=[]
    for _,g in df.sort_values(["upazila","date_dt"]).groupby("upazila",sort=False):
        x=g.copy(); sh=x.rain_z.le(thr)&x.rain_z.notna(); rid=sh.ne(sh.shift(fill_value=False)).cumsum(); rl=sh.groupby(rid).transform("sum").astype(int); rp=sh.groupby(rid).cumcount()+1
        x["dry_shock"]=sh; x["shock_len"]=np.where(sh,rl,0).astype(int); x["shock_pos"]=np.where(sh,rp,0).astype(int); x["shock_start"]=sh&x.shock_pos.eq(1); out.append(x)
    return pd.concat(out,ignore_index=True)
def duration_mask(df,key):
    if key=="single": return df.dry_shock&df.shock_len.eq(1)
    if key=="two": return df.dry_shock&df.shock_len.eq(2)
    if key=="three": return df.dry_shock&df.shock_len.ge(3)
    return df.dry_shock
def qfilter(df,mode):
    if mode=="observed": return df[df.MODIS_source_status.eq("observed")].copy()
    if mode=="coverage": return df[df.MODIS_source_status.eq("observed")&df.MODIS_coverage_proxy.ge(COVERAGE_CUTOFF)].copy()
    return df.copy()
def tqfilter(df,mode,k):
    if mode=="observed": return df[df[f"target_status_lag{k}"].eq("observed")].copy()
    if mode=="coverage": return df[df[f"target_status_lag{k}"].eq("observed")&df[f"target_cov_lag{k}"].ge(COVERAGE_CUTOFF)].copy()
    return df.copy()
def qname(x): return {"high":L("Observed · higher coverage","পর্যবেক্ষিত · বেশি কভারেজ"),"low":L("Observed · lower coverage","পর্যবেক্ষিত · কম কভারেজ"),"interpolated":L("Interpolated","ইন্টারপোলেটেড")}.get(x,x)

