# Extra research-only recovery diagnostic, kept separate from causal claims.
def recovery_table(df,thr,selected,years,months):
    s=add_runs(df,thr); rows=[]
    for up,g in s.groupby("upazila"):
        if up not in selected: continue
        g=g.sort_values("date_dt").reset_index(drop=True)
        for i in g.index[g.shock_start]:
            r=g.loc[i]
            if not(years[0]<=int(r.year)<=years[1] and int(r.month) in months): continue
            run=int(r.shock_len); end=min(i+run-1,len(g)-1); resp=g.loc[i:min(end+2,len(g)-1),["date_dt","ndvi_z"]].dropna()
            if resp.empty: continue
            j=resp.ndvi_z.idxmin(); minz=float(g.loc[j,"ndvi_z"]); mind=pd.Timestamp(g.loc[j,"date_dt"]); rec=np.nan; status=L("No material decline by rule","নিয়মে উল্লেখযোগ্য পতন নেই")
            if minz<-.25:
                status=L("Not recovered within 6 months","৬ মাসে পুনরুদ্ধার নয়"); after=g[(g.date_dt>mind)&(g.date_dt<=mind+pd.DateOffset(months=6))&g.ndvi_z.ge(-.25)]
                if not after.empty:
                    rd=pd.Timestamp(after.iloc[0].date_dt); rec=(rd.year-mind.year)*12+(rd.month-mind.month); status=L("Recovered by dashboard rule","ড্যাশবোর্ড নিয়মে পুনরুদ্ধার")
            rows.append({L("Upazila","উপজেলা"):uname(up),L("Shock start","ধাক্কা শুরু"):pd.Timestamp(r.date_dt).strftime("%Y-%m"),L("Shock duration (months)","ধাক্তার সময়কাল (মাস)"):run,L("Mean rainfall anomaly during run (z)","ধাক্কায় গড় বৃষ্টি বিচ্যুতি (z)"):g.loc[i:end,"rain_z"].mean(),L("Minimum NDVI anomaly (run + 2m)","সর্বনিম্ন NDVI বিচ্যুতি (ধাক্কা + ২মাস)"):minz,L("Months to return ≥ -0.25 SD","≥ -০.২৫ SD-তে ফিরতে মাস"):rec,L("Recovery status","পুনরুদ্ধার অবস্থা"):status})
    return pd.DataFrame(rows)
if view=="Research":
    with tabs[4]:
        with st.expander(L("Exploratory recovery diagnostic","অনুসন্ধানমূলক পুনরুদ্ধার নির্ণায়ক")):
            rt=recovery_table(panel,thr,selected,years,months)
            if rt.empty: st.info(L("No shock runs available under the selected filters.","নির্বাচিত ফিল্টারে কোনো শুষ্ক-ধাক্কা ধারা নেই।"))
            else: st.dataframe(rt.round(3),hide_index=True,use_container_width=True)
            st.caption(L("Transparent rule: a material decline is NDVI anomaly < -0.25 SD; recovery is the first later month within six months with NDVI anomaly ≥ -0.25 SD. This is an exploratory dashboard definition, not an agronomic standard.","স্বচ্ছ নিয়ম: NDVI বিচ্যুতি < -০.২৫ SD হলে উল্লেখযোগ্য পতন; এরপর ৬ মাসের মধ্যে প্রথমবার NDVI ≥ -০.২৫ SD হলে পুনরুদ্ধার। এটি অনুসন্ধানমূলক ড্যাশবোর্ড সংজ্ঞা, কৃষিবৈজ্ঞানিক মানদণ্ড নয়।"))

